def _convert_temperature(value: float, src: str, dst: str) -> float:
    if src == dst:
        return value
    if src == "k":
        celsius = value - 273.15
    elif src == "f":
        celsius = (value - 32) * 5 / 9
    else:
        celsius = value
    if dst == "k":
        return celsius + 273.15
    if dst == "f":
        return celsius * 9 / 5 + 32
    return celsius
